-- One wide row per payment attempt, used by the Rule Simulator so an analyst can write a plain
-- WHERE clause (e.g. "ip_declines_10m >= 5 AND amount < 3") and backtest it.
WITH ip_velocity AS (
    SELECT txn_id,
           count(*)                         OVER w AS ip_attempts_10m,
           count(DISTINCT card_fingerprint) OVER w AS ip_cards_10m,
           sum((result = 'declined')::INT)  OVER w AS ip_declines_10m
    FROM {{ ref('payment_attempts') }}
    WINDOW w AS (PARTITION BY ip ORDER BY ts RANGE BETWEEN INTERVAL 10 MINUTES PRECEDING AND CURRENT ROW)
)
SELECT
    a.txn_id, a.user_id, a.ts, CAST(a.amount AS DOUBLE) AS amount, a.txn_type, a.result, a.decline_reason,
    a.ip, a.device_id, a.bin,
    pm.card_country, coalesce(pm.is_virtual_or_prepaid, false) AS is_virtual_card,
    u.country AS user_country,
    coalesce(pm.card_country <> u.country, false) AS card_country_mismatch,
    date_diff('day', u.signup_ts, a.ts) AS account_age_days,
    is_disposable_email(u.email) AS disposable_email,
    a.device_id IS DISTINCT FROM u.signup_device_id AS not_signup_device,
    v.ip_attempts_10m, v.ip_cards_10m, v.ip_declines_10m
FROM {{ ref('payment_attempts') }} a
JOIN ip_velocity v USING (txn_id)
JOIN {{ source('raw', 'users') }} u USING (user_id)
LEFT JOIN {{ source('raw', 'payment_methods') }} pm USING (pm_id)
